--- Translates an item mod line into Russian.
--- Strips and preserves mod tags (e.g. {crafted}, {implicit}, {range:0.5}).
--- Returns original line as safe fallback if translation not found.
---@param line string|nil
---@return string|nil
function ModTranslationsRU:Translate(line)
    if not line or #line == 0 then
        return line
    end

    -- Extract leading tags like {crafted}, {implicit}, {fractured}, {range:0.5}
    local tags = {}
    local core = line
    while true do
        local tag, rest = core:match("^(%b{})%s*(.*)$")
        if tag and rest then
            table.insert(tags, tag)
            core = rest
        else
            break
        end
    end

    local tagPrefix = #tags > 0 and (table.concat(tags, " ") .. " ") or ""
    if core:match("^Bonded:%s*") then
        tagPrefix = tagPrefix .. "Узы: "
        core = core:gsub("^Bonded:%s*", "")
    end

    -- 1. Exact phrase match
    if self.exact[core] then
        return tagPrefix .. self.exact[core]
    end

    -- 1.1 Dynamic anoint matching: "Allocates <Passive Name>"
    local anointNode = core:match("^Allocates%s+(.+)$")
    if anointNode and not anointNode:find("Jewel%s+socket") then
        local ruNode = (self.notables and self.notables[anointNode]) or (TreeNodesRU and TreeNodesRU.Get and TreeNodesRU:Get(anointNode)) or anointNode
        return tagPrefix .. "Дарует: " .. ruNode
    end

    -- 1.2 Dynamic granted skill matching: "Grants Skill: Level X <Skill Name>" (supports "Level 18" and "Level (1-20)")
    local skillLvl, skillName = core:match("^Grants%s+Skill:%s+Level%s+([%d%(%)%-]+)%s+(.+)$")
    local gnr = GemNamesRU
    if not gnr and LoadModule then
        pcall(function() gnr = LoadModule("Data/GemNamesRU") end)
    end
    if not gnr then
        pcall(function() gnr = require("GemNamesRU") end)
    end
    if skillLvl and skillName then
        local ruSkill = (gnr and gnr.Get and gnr:Get(skillName)) or skillName
        return tagPrefix .. "Дарует умение: " .. ruSkill .. " " .. skillLvl .. " уровня"
    else
        local bareSkill = core:match("^Grants%s+Skill:%s+(.+)$")
        if bareSkill then
            local ruSkill = (gnr and gnr.Get and gnr:Get(bareSkill)) or bareSkill
            return tagPrefix .. "Дарует умение: " .. ruSkill
        end
    end

    -- 1.3 Dynamic radius jewel modifiers
    local smallRadiusMod = core:match("^Small Passive Skills in Radius also grant (.+)$")
    if smallRadiusMod then
        local tRest = self:Translate(smallRadiusMod) or smallRadiusMod
        return tagPrefix .. "Малые пассивные умения в радиусе также дают " .. tRest
    end
    local notableRadiusMod = core:match("^Notable Passive Skills in Radius also grant (.+)$")
    if notableRadiusMod then
        local tRest = self:Translate(notableRadiusMod) or notableRadiusMod
        return tagPrefix .. "Значимые пассивные умения в радиусе также дают " .. tRest
    end
    local passivesRadiusMod = core:match("^Passives in Radius also grant (.+)$")
    if passivesRadiusMod then
        local tRest = self:Translate(passivesRadiusMod) or passivesRadiusMod
        return tagPrefix .. "Пассивные умения в радиусе также дают " .. tRest
    end

    -- 1.4 Unique jewel specific patterns
    local ringType = core:match("^Only affects Passives in (.+) Ring$")
    if ringType then
        local rMap = {
            ["Very Small"] = "очень малого",
            ["Small"] = "малого",
            ["Medium-Small"] = "средне-малого",
            ["Medium"] = "среднего",
            ["Medium-Large"] = "средне-большого",
            ["Large"] = "большого",
            ["Very Large"] = "очень большого",
            ["Massive"] = "огромного",
        }
        return tagPrefix .. "Влияет только на пассивные умения внутри " .. (rMap[ringType] or ringType) .. " кольца"
    end
    local remNum, remName = core:match("^Remembrancing ([%d%(%)%-]+) songworthy deeds by the line of (.+)$")
    if remNum and remName then
        local nameMap = { ["Vorana"] = "Вораны", ["Medved"] = "Медведя", ["Olroth"] = "Олрота" }
        return tagPrefix .. string.format("Воспоминание о %s заслуживающих песни деяниях потомков %s", remNum, nameMap[remName] or remName)
    end
    local gloNum, gloName = core:match("^Glorifying the defilement of ([%d%(%)%-]+) souls in tribute to (.+)$")
    if gloNum and gloName then
        local nameMap = { ["Amanamu"] = "Аманаму", ["Kulemak"] = "Кулемака", ["Kurgal"] = "Кургала", ["Tecrod"] = "Текрода", ["Ulaman"] = "Уламана" }
        return tagPrefix .. string.format("Прославление осквернения %s душ в дань уважения %s", gloNum, nameMap[gloName] or gloName)
    end
    local conqFaction = core:match("^Passives in radius are Conquered by the (.+)$")
    if conqFaction then
        if conqFaction == "Kalguur" then return tagPrefix .. "Пассивные умения в радиусе покорены калгурами" end
        if conqFaction == "Abyssals" then return tagPrefix .. "Пассивные умения в радиусе покорены Бездной" end
        return tagPrefix .. "Пассивные умения в радиусе покорены " .. conqFaction
    end
    local sinCount = core:match("^Allocates (%d+) Sinister Jewel sockets?$")
    if sinCount then
        return tagPrefix .. string.format("Назначает %s зловещих гнезда для самоцветов", sinCount)
    end
    local splitClass = core:match("^Can Allocate Passive Skills from the (.+)'s starting point$")
    if splitClass then
        local clsMap = {
            ["Ranger"] = "Охотницы",
            ["Shadow"] = "Бандита",
            ["Sorceress"] = "Волшебницы",
            ["Warrior"] = "Воина",
            ["Mercenary"] = "Наёмника",
            ["Templar"] = "Жреца",
        }
        return tagPrefix .. "Можно выбирать пассивные умения с начальной точки " .. (clsMap[splitClass] or splitClass)
    end

    -- 1.5 Direct full-line template match (non-numeric phrases stored in templates)
    if self.templates[core] then
        return tagPrefix .. self.templates[core]
    end

    -- 2. Special regex rules (multi-number and parameterized patterns)
    for _, rule in ipairs(self.specialRules) do
        local m1, m2 = core:match(rule.pattern)
        if m1 then
            local safeM1 = m1:gsub("%%", "%%%%")
            local out = rule.replacement:gsub("%%1", safeM1)
            if m2 then
                local safeM2 = m2:gsub("%%", "%%%%")
                out = out:gsub("%%2", safeM2)
            end
            return tagPrefix .. out
        end
    end

    -- 3. Range prefix: +(10-19) to maximum Life / +(10-19)% to Fire Resistance
    local rng, rngCore = core:match("^([%+%-]?%(%d+[%-–]%d+%)%%?)%s+(.+)$")
    if rng and rngCore and self.templates[rngCore] then
        return tagPrefix .. rng .. " " .. self.templates[rngCore]
    end

    -- 4. Numeric prefix: +75 to maximum Life / +35% to Fire Resistance / 12% increased Attack Speed
    local num, numCore = core:match("^([%+%-]?%d+%.?%d*%%?)%s+(.+)$")
    if num and numCore and self.templates[numCore] then
        local tpl = self.templates[numCore]
        if numCore:find("Modifier[s]? allowed") then
            return tagPrefix .. num .. " к допустимому количеству " .. (numCore:find("Prefix") and "префиксов" or "суффиксов")
        end
        return tagPrefix .. num .. " " .. tpl
    end

    -- 5. Case-insensitive template fallback for UPPERCASE or mixed case mod lines
    if num and numCore then
        local numCoreLower = numCore:lower()
        for tKey, tVal in pairs(self.templates) do
            if tKey:lower() == numCoreLower then
                if numCoreLower:find("modifier[s]? allowed") then
                    return tagPrefix .. num .. " к допустимому количеству " .. (numCoreLower:find("prefix") and "префиксов" or "суффиксов")
                end
                return tagPrefix .. num .. " " .. tVal
            end
        end
    end

    -- 6. Case-insensitive exact & template match fallback
    local coreLower = core:lower()
    for eKey, eVal in pairs(self.exact) do
        if eKey:lower() == coreLower then
            return tagPrefix .. eVal
        end
    end
    for tKey, tVal in pairs(self.templates) do
        if tKey:lower() == coreLower then
            return tagPrefix .. tVal
        end
    end

    -- Log untranslated mod line (source: "MOD")
    local fullLine = tagPrefix .. core
    if RULogger and main and main.logUntranslatedRU then
        RULogger.Log("MOD", fullLine)
    end

    return line
end

return ModTranslationsRU
